:root {
  /* ========== 色彩体系 ========== */
  /* 県庁の落ち着いたトーン：深い紺と石灰色を基調に、公務的な信頼感と厳格性を表現 */
  --primary: #2c3e50;
  --primary-hover: #1a252f;

  /* 背景：薄い石灰色（公文書のような質感）に微かな緑味を加えた落ち着き */
  --bg-main: #f0ede8;
  --bg-card: #e8e5e0;
  --bg-sidebar: #ebe8e3;
  --top-bar-bg: #2c3e50;
  --top-bar-border: #1a252f;

  /* 境界線：石灰色系で統一、やや濃いめで公式感を強調 */
  --border: #c9c5bd;

  /* テキスト：深い紺で、落ち着いた読みやすさ */
  --text: #1a1f26;
  --text-muted: #6b7280;

  /* ステータス・アラート色 */
  --success: #3d7e4a;
  --warning: #a67c52;
  --error: #8b4545;
  --info: #4a6fa5;

  /* ========== タイポグラフィ ========== */
  --font-family: "Segoe UI", "Hiragino Sans", "Yu Gothic", sans-serif;

  /* ========== 寸法・間隔 ========== */
  --space-unit: 8px;
  --control-height: 40px;

  /* 角丸：公式感を損なわないよう控えめに */
  --radius-card: 4px;
  --radius-control: 3px;

  /* ========== 枠線 ========== */
  --border-width: 1px;

  /* ========== 影・奥行き ========== */
  --shadow-card: 0 1px 3px rgba(28, 31, 38, 0.08);

  /* ========== モーション ========== */
  --motion-duration: 200ms;

  /* ========== 質感・テクスチャ ========== */
  /* 公文書の紙質感：微細な織目模様で、デジタルながら公式文書の重厚さを表現 */
  --surface-texture: 
    repeating-linear-gradient(
      90deg,
      transparent,
      transparent 2px,
      rgba(172, 167, 154, 0.03) 2px,
      rgba(172, 167, 154, 0.03) 4px
    ),
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      rgba(172, 167, 154, 0.02) 2px,
      rgba(172, 167, 154, 0.02) 4px
    );
  --surface-texture-size: 100% 100%;
  --surface-texture-position: 0 0;
}
